function renderOverview(){const nmcTracks=data.tracks.filter(t=>!t.wpSynced);const allRights=nmcTracks.flatMap(t=>t.rightsData||[]),done=allRights.filter(r=>r[1]).length,attention=data.tracks.filter(t=>!t.status||Number(t.score||0)<85||!t.rightsData?.every(r=>r[1])).slice(0,12);const lockedArtists=data.artists.filter(a=>a.status==='LOCKED').length,blackSignalTracks=nmcTracks.filter(t=>t.score>=95).length,rightsPercent=allRights.length?Math.round(done/allRights.length*100):0,artistScore=data.artists.length?Math.round(lockedArtists/data.artists.length*100):0,trackScore=nmcTracks.length?Math.round(blackSignalTracks/nmcTracks.length*100):0,sysScore=Math.round((artistScore+trackScore+rightsPercent)/3);$('#systemScore').textContent=sysScore+'%';$('#artistMetric').textContent=lockedArtists;$('#trackMetric').textContent=data.tracks.length;$('#blackMetric').textContent=blackSignalTracks;$('#rightsMetric').textContent=rightsPercent+'%';$('#attentionList').innerHTML=attention.map(t=>`<div class="attention"><span class="attention-icon">${t.score?'◆':'♫'}</span><div><b>${t.title}</b><small>${t.artist} · ${t.status||'Unclassified'}</small></div><span class="tag">${t.score||'UNSCORED'}</span></div>`).join('')+`<div class="attention"><span class="attention-icon">!</span><div><b>${allRights.length-done} provenance fields incomplete</b><small>Across ${data.tracks.length} track records · open Catalogue for full queue</small></div><span class="tag">RIGHTS</span></div>`;renderCatalogue()}
function catalogueNeedsWork(t){return !t.status||Number(t.score||0)<85||!t.rightsData?.length||!t.rightsData.every(r=>r[1])}
function renderCatalogue(){if(!$('#catalogueTable'))return;const search=($('#catalogueSearch').value||'').trim().toLowerCase(),artistFilter=$('#catalogueArtist').value,statusFilter=$('#catalogueStatus').value,attentionOnly=$('#catalogueNeedsAttention').checked,artists=[...new Set(data.tracks.map(t=>t.artist).filter(Boolean))].sort(),statuses=[...new Set(data.tracks.map(t=>t.status||'Unclassified'))].sort();$('#catalogueArtist').innerHTML='<option value="">All artists</option>'+artists.map(name=>`<option value="${name}">${name}</option>`).join('');$('#catalogueStatus').innerHTML='<option value="">All statuses</option>'+statuses.map(status=>`<option value="${status}">${status}</option>`).join('');$('#catalogueArtist').value=artists.includes(artistFilter)?artistFilter:'';$('#catalogueStatus').value=statuses.includes(statusFilter)?statusFilter:'';const filtered=data.tracks.filter(t=>{const haystack=`${t.title||''} ${t.artist||''} ${t.id||''}`.toLowerCase(),status=t.status||'Unclassified';return (!search||haystack.includes(search))&&(!artistFilter||t.artist===artistFilter)&&(!statusFilter||status===statusFilter)&&(!attentionOnly||catalogueNeedsWork(t))}),rightsReady=data.tracks.filter(t=>t.rightsData?.length&&t.rightsData.every(r=>r[1])).length,attention=data.tracks.filter(catalogueNeedsWork).length,visible=filtered.slice(0,150);$('#catalogueTracks').textContent=data.tracks.length;$('#catalogueArtists').textContent=artists.length;$('#catalogueBlack').textContent=data.tracks.filter(t=>Number(t.score||0)>=95).length;$('#catalogueRights').textContent=rightsReady;$('#catalogueAttention').textContent=attention;$('#catalogueVisible').textContent=`${filtered.length} VISIBLE`;$('#catalogueTable').innerHTML=`<div class="catalogue-row head"><span>Recording</span><span>Artist</span><span>Status</span><span>QC</span><span>Rights</span><span>Source</span><span>Action</span></div>`+(visible.length?visible.map(t=>{const complete=t.rightsData?.length&&t.rightsData.every(r=>r[1]),done=(t.rightsData||[]).filter(r=>r[1]).length,total=(t.rightsData||[]).length;return `<div class="catalogue-row ${t.id===selectedTrackId?'selected':''}"><div class="catalogue-title"><b>${t.title||'Untitled recording'}</b><small>${t.id||'NO ID'}</small></div><b>${t.artist||'UNASSIGNED'}</b><span class="catalogue-status">${t.status||'UNCLASSIFIED'}</span><span class="catalogue-score">${Number(t.score||0)||'—'}</span><span class="catalogue-rights ${complete?'pass':'fail'}">${done}/${total||12}</span><span class="catalogue-source">${t.wpSynced?'WORDPRESS':'SIGNAL OS'}</span><button class="button ghost small" data-catalogue-track="${t.id}">Open</button><button class="button ghost small" data-edit-track="${t.id}">Edit</button><button class="button ghost small" data-del-track="${t.id}">Del</button></div>`}).join(''):'<p class="catalogue-empty">No recordings match these filters.</p>');$('#catalogueNote').textContent=filtered.length>150?`Showing the first 150 of ${filtered.length} matches. Narrow the filters to see a specific recording.`:`Showing ${filtered.length} catalogue record${filtered.length===1?'':'s'}.`;$$('[data-catalogue-track]').forEach(button=>button.onclick=()=>{selectedTrackId=button.dataset.catalogueTrack;data.selectedTrackId=selectedTrackId;save();renderTrackContext();navigate('track')});if(typeof NMC_wireCrudButtons==='function')NMC_wireCrudButtons();}
($('#catalogueSearch')||{}).oninput=renderCatalogue;($('#catalogueArtist')||{}).onchange=renderCatalogue;($('#catalogueStatus')||{}).onchange=renderCatalogue;($('#catalogueNeedsAttention')||{}).onchange=renderCatalogue;($('#catalogueReset')||{}).onclick=()=>{$('#catalogueSearch').value='';$('#catalogueArtist').value='';$('#catalogueStatus').value='';$('#catalogueNeedsAttention').checked=false;renderCatalogue()};
