(function(){
  const GENRES=['afrobeats','afro-drill','afro-house','afro-soul','afro-rnb','amapiano','afropop','highlife','gospel','soul','kuduro','afro-noir','afro-fusion','other'];
  if(!document.getElementById('nmc-crud-style')){
    const st=document.createElement('style');st.id='nmc-crud-style';
    st.textContent='.nmc-modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center;z-index:9999}.nmc-modal{background:#12100c;border:1px solid #b98b2e;border-radius:10px;padding:22px;width:min(460px,92vw);max-height:90vh;overflow:auto;color:#f0e6cf;font-size:13px}.nmc-modal h3{margin:0 0 14px;color:#e9c46a;letter-spacing:.04em}.nmc-modal label{display:block;margin:10px 0;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#c9b98f}.nmc-modal input,.nmc-modal select{width:100%;margin-top:5px;padding:9px 10px;background:#0b0a07;border:1px solid #3a3320;border-radius:6px;color:#f0e6cf;font-size:13px;text-transform:none;letter-spacing:0}.nmc-modal .nmc-row{display:flex;gap:12px}.nmc-modal .nmc-row label{flex:1}.nmc-modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.nmc-modal-msg{margin-top:10px;color:#e07a5f;min-height:16px}#nmcAddTrackBtn{margin-left:8px}';
    document.head.appendChild(st);
  }
  const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
  const tkSave=p=>api('/api/site/track-save',{method:'POST',body:JSON.stringify(p)});
  const tkDelete=id=>api('/api/site/track-delete',{method:'POST',body:JSON.stringify({id})});
  const fileB64=f=>new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});
  const wpId=t=>t.wpPostId||t.id;
  async function refresh(){try{if(typeof syncTracksFromWP==='function')await syncTracksFromWP(true);}catch(e){}renderCatalogue();}
  window.openTrackEditor=function(track){
    const isEdit=!!(track&&track.id);
    const aOpts=((window.data&&data.artists)||[]).map(a=>`<option value="${esc(a.wpPostId||a.post_id||'')}">${esc(a.name||a.title||'')}</option>`).join('');
    const w=document.createElement('div');w.className='nmc-modal-backdrop';
    w.innerHTML=`<div class="nmc-modal"><h3>${isEdit?'Edit track':'Add track'}</h3>`+
      `<label>Title<input id="tkT" value="${esc(track&&track.title)}"></label>`+
      `<label>Artist name<input id="tkA" value="${esc(track&&track.artist)}"></label>`+
      `<label>Link to artist page (optional)<select id="tkAi"><option value="">— none —</option>${aOpts}</select></label>`+
      `<div class="nmc-row"><label>Genre<select id="tkG">${GENRES.map(g=>`<option${track&&track.genre===g?' selected':''}>${g}</option>`).join('')}</select></label><label>BPM<input id="tkB" type="number" value="${esc(track&&track.bpm)}"></label></div>`+
      `<label>Status<select id="tkS"><option value="publish"${(!track||track.status!=='draft')?' selected':''}>Live (on radio)</option><option value="draft"${track&&track.status==='draft'?' selected':''}>Draft</option></select></label>`+
      (isEdit?'':`<label>Audio file (mp3/wav)<input id="tkF" type="file" accept="audio/*"></label>`)+
      `<div class="nmc-modal-actions"><button class="button ghost" id="tkC">Cancel</button><button class="button" id="tkSv">${isEdit?'Save changes':'Add to catalogue'}</button></div>`+
      `<div class="nmc-modal-msg" id="tkM"></div></div>`;
    document.body.appendChild(w);
    const q=id=>w.querySelector('#'+id),close=()=>w.remove();
    q('tkC').onclick=close;w.onclick=e=>{if(e.target===w)close()};
    q('tkSv').onclick=async()=>{
      const b=q('tkSv'),m=q('tkM');
      const p={title:q('tkT').value.trim(),artist_name:q('tkA').value.trim(),artist_id:q('tkAi').value,genre:q('tkG').value,bpm:q('tkB').value.trim(),status:q('tkS').value};
      if(isEdit)p.id=wpId(track);
      if(!p.title){m.textContent='Title is required.';return;}
      const fi=q('tkF');
      if(!isEdit&&(!fi||!fi.files[0])){m.textContent='Choose an audio file.';return;}
      b.disabled=true;b.textContent='Saving…';m.textContent='';
      try{
        if(fi&&fi.files[0]){const f=fi.files[0];if(f.size>9*1024*1024)throw new Error('Audio too large (max ~9MB). Export a smaller MP3.');p.audio_data=await fileB64(f);p.audio_name=f.name;}
        await tkSave(p);
        toast(isEdit?'Track updated on nairamusic.com':'Track added — live on radio');
        try{logActivity(isEdit?'TRACK EDITED':'TRACK ADDED',`${p.title} → nairamusic.com`);}catch(e){}
        close();refresh();
      }catch(e){m.textContent=e.message||'Save failed';b.disabled=false;b.textContent=isEdit?'Save changes':'Add to catalogue';}
    };
  };
  window.confirmDeleteTrack=async function(track){
    if(!confirm('Delete "'+track.title+'"?\nIt will be moved to Trash on nairamusic.com and removed from radio rotation.'))return;
    try{await tkDelete(wpId(track));toast('Track deleted');try{logActivity('TRACK DELETED',track.title);}catch(e){}const i=data.tracks.indexOf(track);if(i>=0){data.tracks.splice(i,1);save();}refresh();}catch(e){toast(e.message||'Delete failed');}
  };
  window.NMC_wireCrudButtons=function(){
    document.querySelectorAll('[data-edit-track]').forEach(bn=>bn.onclick=e=>{e.stopPropagation();const t=data.tracks.find(x=>String(x.id)===bn.dataset.editTrack);if(t)openTrackEditor(t);});
    document.querySelectorAll('[data-del-track]').forEach(bn=>bn.onclick=e=>{e.stopPropagation();const t=data.tracks.find(x=>String(x.id)===bn.dataset.delTrack);if(t)confirmDeleteTrack(t);});
    const reset=document.getElementById('catalogueReset');
    if(reset&&!document.getElementById('nmcAddTrackBtn')){const add=document.createElement('button');add.id='nmcAddTrackBtn';add.className='button';add.textContent='+ Add track';add.onclick=()=>openTrackEditor(null);reset.parentNode.insertBefore(add,reset.nextSibling);}
  };
})();
function renderTrackSelector(){const select=$('#currentTrack');select.innerHTML=`<option value="" ${!selectedTrackId?'selected':''}></option>`+data.tracks.map(t=>`<option value="${t.id}" ${t.id===selectedTrackId?'selected':''}>${t.artist} — ${t.title}</option>`).join('');select.onchange=()=>{selectedTrackId=select.value;data.selectedTrackId=selectedTrackId;save();renderTrackContext();toast(`Current track: ${currentTrack().title}`)}}
async function renderTrackContext(){loadTrackForm();renderTrackSelector();renderCatalogue();}
