function renderBibleFoundation(){const sec=$('#artists');if(!sec||sec.querySelector('.bible-foundation'))return;const grid=sec.querySelector('.grid.artist-grid');if(!grid)return;const spectrum=[['Grief','Fantasma','65–75'],['Seduction','Pastor Flow','70–85'],['Elder weight','Rajebu','88–95'],['Skepticism','DJ Na Lie','100–140'],['Philosophy','Boboyi','102–108'],['Mysticism','Asa Brugga','110–118'],['Joy','Lyrikal Flame','112–120'],['Revolution','Makasi','115–125'],['Ceremony','Zooboi','125–140'],['Diaspora','Reign','130–145'],['Chaos','Nova Venom','140–150']].map(([e,a,b])=>'<div class="spectrum-row"><span class="spectrum-emotion">'+e+'</span><strong>'+a+'</strong><span class="spectrum-bpm">'+b+' BPM</span></div>').join('');const f=document.createElement('div');f.className='bible-foundation';f.innerHTML='<details class="bible-panel"><summary><span class="eyebrow">NMC MANIFESTO</span><span class="bible-summary-sub">The Cartel\'s founding truth</span></summary><div class="bible-content"><p>NMC isn\'t entertainment. It\'s <strong>DOCUMENTATION</strong>. Pan-African survival, struggle, joy, grief, revolution, and transcendence — voices for people whose stories aren\'t told. They honour ancestors while pushing boundaries. They\'re rooted in tradition while creating the future.</p><p>Not a label. A cartel — sovereign artists who chose each other. No advances. No copyright grabs. Every artist controls their masters. What they share: a manifesto, a frequency, and the question: <strong>"Na lie?"</strong></p><p class="bible-model">Model: Gorillaz/MF DOOM lineage · Wu-Tang crew structure · Fela Kuti political consciousness · AI-transparent — disclosed openly as marketing strength.</p></div></details><details class="bible-panel"><summary><span class="eyebrow">NMC CODE</span><span class="bible-summary-sub">Seven signed pledges — on paper, stored in Hackney</span></summary><div class="bible-content"><ol class="nmc-code-list"><li><strong>I OWN MY MASTERS.</strong> The Cartel is a platform, not a contract.</li><li><strong>I TELL THE TRUTH IN MY LANGUAGE.</strong> No hollow exoticism. No performing Africanness for a Western gaze.</li><li><strong>I PROTECT THE CARTEL.</strong> What is said in sessions, stays in sessions.</li><li><strong>I SHOW UP FOR THE OTHERS.</strong> A Cartel member in need calls one number. The Cartel answers.</li><li><strong>THE AUDIENCE IS FAMILY.</strong> We document for our people. A ticket-holder is a witness, not a consumer.</li><li><strong>WE DO NOT COMPETE.</strong> NMC artists build each other\'s platforms. A rising tide. Always.</li><li><strong>THE QUESTION IS SACRED.</strong> "Na lie?" is a method. Every NMC track must earn its own answer.</li></ol><p class="bible-banned"><strong>BANNED:</strong> Nnamdi · Kanu · IPOB &nbsp;|&nbsp; <strong>CARTEL LANGUAGE:</strong> "Naira Cartel" not "gang"</p></div></details><details class="bible-panel"><summary><span class="eyebrow">THE FORMATION</span><span class="bible-summary-sub">How NMC began — Hackney, E8, 2021</span></summary><div class="bible-content"><p>2021. A warehouse in Hackney, E8. DJ Na Lie had been running an irregular Friday night called "Signal Lost" — no social media, location dropped by WhatsApp at 10PM, capacity strictly 200.</p><p>The night Boboyi showed up, he\'d just arrived from Lagos on a visitor visa. Na Lie played an instrumental built from sampled SARS police radio traffic. Boboyi freestyled over it for 11 minutes. Nobody in the room moved. When he finished, Na Lie said: "Na lie?" Boboyi said: "Ọba kò sọ̀rọ̀ lẹ́ẹ̀mejì." Neither needed a translator.</p><p>What followed was not planned. Zooboi came because Boboyi called him. Lyrikal Flame was found through a viral video sent at 3AM without comment. Fantasma\'s track was shared with only: "We need this." Nova Venom was already in the session when Na Lie arrived; nobody has asked how. Asa Brugga said nothing across two sessions then sent a finished track: "Agua y fuego." Makasi arrived with a bass guitar: "Can I name the people they won\'t name?" Pastor Flow had produced three tracks before anyone realised he\'d joined. Rajebu was found through 33 scars and a lifetime of Ajegunle compressed into a baritone.</p><p><em>No founding meeting. No term sheets. No pitch deck. NMC formed the way all real things form: people who needed each other found each other, and a frequency was born.</em></p></div></details><details class="bible-panel"><summary><span class="eyebrow">ENERGY SPECTRUM</span><span class="bible-summary-sub">Emotional map of the roster — slowest to fastest</span></summary><div class="bible-content"><div class="spectrum-grid">'+spectrum+'</div><div class="collab-trios"><p class="eyebrow" style="margin-top:1.25rem;margin-bottom:.5rem">POWER TRIOS</p><p><strong>Explosive Male Energy:</strong> Boboyi + Zooboi + Makasi — philosophy + primal + politics</p><p><strong>Female Force:</strong> Asa Brugga + Lyrikal Flame + Nova Venom — mysticism + joy + chaos</p><p><strong>Elder Council:</strong> Rajebu + DJ Na Lie + Boboyi — survival + skepticism + philosophy</p></div></div></details><details class="bible-panel"><summary><span class="eyebrow">TRINITY MASCOTS</span><span class="bible-summary-sub">The visual symbols of NMC</span></summary><div class="bible-content"><div class="trinity-grid"><div class="trinity-item"><span class="trinity-symbol">🥁</span><strong>Àyàn</strong><p>Talking drum · Wisdom, culture, ancestral communication</p></div><div class="trinity-item"><span class="trinity-symbol">🚌</span><strong>Dango</strong><p>Danfo bus · Movement, hustle, Lagos energy</p></div><div class="trinity-item"><span class="trinity-symbol">✊</span><strong>Unity</strong><p>Afro pick + Black Power fist · Pan-African resistance and pride</p></div></div></div></details>';grid.parentNode.insertBefore(f,grid);}
