async function renderLeaderboard(){const panel=$('#leaderboardPanel');if(!panel)return;try{const d=await api('/api/radio/charts');const list=Array.isArray(d)?d:(d&&(d.tracks||d.top_tracks))||[];if(!list.length){panel.innerHTML='<p class="radio-empty">No chart data yet — plays are still accumulating.</p>';return;}panel.innerHTML=list.slice(0,20).map((t,i)=>{const rank=t.rank||i+1;const mv=t.movement||{};const dir=mv.direction==='up'?'▲ '+(mv.places||''):mv.direction==='down'?'▼ '+(mv.places||''):mv.direction==='new'?'NEW':'–';const col=mv.direction==='up'?'var(--green,#3fbf6a)':mv.direction==='down'?'#d9534f':'var(--muted,#9a9)';const plays=t.play_count!=null?t.play_count:(t.plays!=null?t.plays:(t.streams||0));const cover=t.cover||'';return `<div style="display:flex;align-items:center;gap:10px;padding:8px 4px;border-bottom:1px solid var(--line,#2a2a1f)"><span style="min-width:24px;font-weight:700;color:var(--gold,#d8b45a);font-variant-numeric:tabular-nums">${rank}</span>${cover?`<img src="${cover}" alt="" style="width:34px;height:34px;border-radius:5px;object-fit:cover">`:'<span style="width:34px;height:34px;display:grid;place-items:center;background:#1a1a12;border-radius:5px">♫</span>'}<div style="flex:1;min-width:0"><b style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${t.title||'Untitled'}</b><small style="color:var(--muted,#9a9)">${t.artist||''}</small></div><span style="min-width:48px;text-align:right;font-size:.75rem;color:${col}">${dir}</span><span style="min-width:70px;text-align:right;font-variant-numeric:tabular-nums;color:var(--muted,#9a9);font-size:.8rem">${plays} ${plays===1?'play':'plays'}</span></div>`}).join('');}catch(e){panel.innerHTML=`<p class="fail">Leaderboard unavailable: ${e.message}</p>`;}}
// ── STUDIO: Visuals (Kling) · Social captions · Distribution (DistroKid) ─────
function _studioArtist(){return ($('#launchArtistSelect')&&$('#launchArtistSelect').value)||(currentTrack()&&currentTrack().artist)||''}
function _studioStore(a){const k=(a||'').toUpperCase().replace(/[^A-Z]/g,'');if(!data.artistPrompts)data.artistPrompts={};if(!data.artistPrompts[k])data.artistPrompts[k]={};return data.artistPrompts[k]}
function _klingSeed(a){const dna=dnaFor(a)||{};const art=(data.artists||[]).find(x=>x.name&&x.name.toLowerCase()===String(a).toLowerCase())||{};const visual=art.visual||art.visualIdentity||'';const style=dna.style||dna.instrumental||'';return `Music cover art / performance visual for ${a}. ${visual?visual+'. ':''}World and mood from the sound: ${style||'Afrobeats, dark, cinematic'}. Cinematic lighting, high detail, square 1:1 cover framing (also export a 9:16 cut for Reels/Shorts). No text, no watermark, no logo.`}
function _socialCaption(platform,a,t){const title=(t&&t.title)||'the new single';const hook=(dnaFor(a)||{}).hook||'';const tags=`#${String(a||'NMC').replace(/[^A-Za-z0-9]/g,'')} #NairaMusic #NMC #NMCSignal`;const base=`${a} — “${title}”`;if(platform==='YouTube')return `${base}\n\nThe official Naira Music release${hook?` — “${hook}”`:''}. Out now on NMC Signal. Subscribe for new NMC drops.\n\n${tags} #NewMusic`;if(platform==='Instagram')return `${base} 🔊\n${hook||'New signal from the Cartel.'}\nSave it. Share it. Run it up.\n\n${tags} #Reels`;if(platform==='TikTok')return `${a} - ${title} 🎧 which part hits hardest?\n${tags} #fyp #afrobeats`;return `${base} is out now on Naira Music. ${hook} ${tags}`.replace(/\s+/g,' ').trim()}
function NMC_renderStudio(){if(!$('#klingPrompt'))return;const a=_studioArtist(),t=currentTrack(),store=a?_studioStore(a):{};
  // Visuals
  const kp=$('#klingPrompt');if(kp){kp.value=(store.visualPrompt!=null&&store.visualPrompt!=='')?store.visualPrompt:(a?_klingSeed(a):'');kp.oninput=()=>{if(a){_studioStore(a).visualPrompt=kp.value;save();_syncSoon();}};}
  const ka=$('#klingAssets');if(ka){const list=(store.visuals||[]);ka.innerHTML=list.length?list.slice().reverse().map((v,i)=>`<div style="display:flex;gap:8px;align-items:center;padding:6px 0;border-top:1px solid var(--line)"><span class="tag">${v.type||'ASSET'}</span><a href="${v.url}" target="_blank" rel="noopener" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.78rem">${v.url}</a><button class="button ghost small" data-kling-del="${list.length-1-i}">×</button></div>`).join(''):'<p style="color:var(--muted);font-size:.78rem">No visuals logged yet.</p>';$$('[data-kling-del]').forEach(b=>b.onclick=()=>{const s=_studioStore(a);s.visuals.splice(+b.dataset.klingDel,1);save();_syncSoon();NMC_renderStudio();});}
}
// one-time Studio wiring
(function(){
  const cp=$('#klingCopy');if(cp)cp.onclick=()=>{navigator.clipboard.writeText($('#klingPrompt').value||'');toast('Visual prompt copied');};
  const kl=$('#klingLog');if(kl)kl.onclick=()=>{const a=_studioArtist(),url=($('#klingResultUrl').value||'').trim();if(!a){toast('Select an artist first');return;}if(!url){toast('Paste the Kling URL');return;}const s=_studioStore(a);s.visuals=s.visuals||[];const type=/\.(mp4|mov|webm)(\?|$)/i.test(url)?'VIDEO':'IMAGE';s.visuals.push({url,type,at:new Date().toISOString()});save();_syncSoon();$('#klingResultUrl').value='';($('#klingState')||{}).textContent='Attached to '+a;NMC_renderStudio();toast('Visual attached to '+a);};
  const kpc=$('#klingPushCover');if(kpc)kpc.onclick=async()=>{const t=currentTrack(),url=($('#klingResultUrl').value||'').trim();const wpId=t&&(t.wpPostId||(/^\d+$/.test(String(t.id))?t.id:(String(t.id).match(/(\d+)/)||[])[1]));if(!t){toast('Open a track from the Catalogue first');return;}if(!wpId){toast('This track isn’t on the website yet — publish it first');return;}if(!url){toast('Paste the Kling image URL');return;}($('#klingState')||{}).textContent='Pushing cover…';try{const r=await api('/api/site/track-cover',{method:'POST',body:JSON.stringify({id:Number(wpId),cover_url:url})});($('#klingState')||{}).textContent='Cover set on website ✓';toast('Track cover updated on nairamusic.com');logActivity('COVER PUSHED',`${t.artist} — ${t.title}`);}catch(e){($('#klingState')||{}).textContent='Endpoint not installed — see Desktop snippet';toast('Cover endpoint not installed yet');}};
  // refresh studio when the launcher artist changes
  document.addEventListener('change',e=>{if(e.target&&e.target.id==='launchArtistSelect')NMC_renderStudio();});
})();
// ── AI SONGWRITER (Claude via /api/ai/generate) ──────────────────────────────
async function _aiGen(system,prompt,max){const r=await api('/api/ai/generate',{method:'POST',body:JSON.stringify({system,prompt,max_tokens:max||1600})});if(!r||!r.ok){const e=new Error((r&&r.error)||'AI request failed');e.needsKey=r&&r.needsKey;e.msg=r&&r.message;throw e;}return (r.text||'').trim();}
function _artistBrief(a){const dna=dnaFor(a)||{};const art=(data.artists||[]).find(x=>x.name&&x.name.toLowerCase()===String(a).toLowerCase())||{};const st=_studioStore(a);const L=['Artist: '+a];if(dna.style)L.push('Style DNA: '+dna.style);if(dna.instrumental)L.push('Instrumental DNA: '+dna.instrumental);if(art.genre)L.push('Genre: '+art.genre);if(art.origin)L.push('Origin: '+art.origin);if(art.signature)L.push('Signature phrase: '+art.signature);if(art.bio)L.push('Bio: '+String(art.bio).slice(0,400));if(st.persona)L.push('Suno voice persona: '+st.persona);return L.join('\n');}
function _setLaunchMode(mode){const el=$('#launchMode');if(!el)return;if(el.textContent.trim().toLowerCase()!==mode&&$('#launchToggleMode'))$('#launchToggleMode').click();}
function _aiBtns(d){['aiGenAll','aiGenInstrumental','aiGenVocal','aiGenLyrics'].forEach(id=>{const b=$('#'+id);if(b)b.disabled=d;});}
function _aiSay(m){const s=$('#aiState');if(s)s.textContent=m||'';}
async function _aiRun(kind){const a=_studioArtist();if(!a){toast('Pick an artist in the launcher above');return;}const concept=(($('#aiConcept')&&$('#aiConcept').value)||'').trim();const explicit=!$('#aiExplicit')||$('#aiExplicit').checked;const brief=_artistBrief(a);const store=_studioStore(a);_aiBtns(true);
  try{
    if(kind==='instrumental'||kind==='all'){_aiSay('Writing full instrumental…');const sys="You are an elite Afrobeats/Afro-fusion music producer composing FULL Suno AI instrumentals for the Naira Music Cartel (NMC). You output a complete, ready-to-render instrumental arrangement that will sound like finished music — never a short description.";const pr=brief+"\n\nSong concept: "+(concept||"(use the artist DNA)")+"\n\nCompose a FULL instrumental for Suno that renders as complete music. Output exactly two parts and nothing else:\n1) STYLE: one line — genre, exact BPM, key, mood, and the core instruments.\n2) ARRANGEMENT: the whole song section by section using [bracketed] tags with bar counts and the specific instruments, riffs, dynamics and transitions in each section. Cover it start to finish, e.g.: [Intro - 8 bars: ...] [Build - 8 bars: ...] [Drop/Hook - 16 bars: ...] [Groove/Verse bed - 16 bars: ...] [Breakdown - 8 bars: ...] [Second Drop - 16 bars: ...] [Bridge - 8 bars: ...] [Final Drop - 16 bars: ...] [Outro - 8 bars: ...].\nIt MUST be fully instrumental — no vocals, no vocalising, no ad-libs, no chops. End with a line beginning \"Exclude:\" listing: vocals, singing, vocalising, ad-libs, vocal chops, choir, spoken word, rap, lyrics, humming, whispers, breaths.";store.instrumental=await _aiGen(sys,pr,2000);save();_syncSoon();}
    if(kind==='vocal'||kind==='all'){_aiSay('Writing vocal prompt…');const sys="You are an elite Afrobeats/Afro-fusion producer writing Suno AI STYLE prompts for vocal takes for NMC. Output ONLY the prompt text.";const pr=brief+"\n\nSong concept: "+(concept||"(use the artist DNA)")+"\n\nWrite a Suno VOCAL/STYLE prompt: one dense paragraph — genre, BPM, key, the vocal character (register, tone, cadence, language/accent), hook style, and the core instruments. "+(explicit?"EXPLICIT allowed.":"Keep it clean.");store.vocal=await _aiGen(sys,pr,900);save();_syncSoon();}
    if(kind==='lyrics'||kind==='all'){_aiSay('Writing lyrics…');const sys="You are a world-class songwriter and topliner for the Naira Music Cartel (NMC). You write complete, radio-ready songs in each artist's authentic voice, cadence and language mix, with a huge chantable hook and vivid, specific imagery — never generic filler. Output ONLY the lyrics with [section] tags.";const pr=brief+"\n\nSong concept: "+(concept||"(use the artist DNA)")+"\n\n"+(store.instrumental?("The instrumental the vocals sit on (match its sections and energy):\n"+store.instrumental+"\n\n"):"")+"Write a COMPLETE song. Structure: [Intro], [Verse 1] (fully written, ~16 bars), [Pre-Hook], [Hook] (the biggest, most repeatable line — land it on the drop), [Verse 2] (fully written, ~16 bars), [Bridge], [Hook], [Outro]. Write the verses out in full — never placeholders. Put ad-libs in (parentheses). Match the artist's cadence, slang and language mix exactly, and keep the imagery specific and true to the artist's world. "+(explicit?"Explicit language is allowed and encouraged where it fits the artist.":"Keep it clean.")+" Output ONLY the lyrics with [section] tags.";store.lyrics=await _aiGen(sys,pr,2200);save();_syncSoon();}
    if(typeof initSunoLauncher==='function')initSunoLauncher();
    if(kind==='instrumental')_setLaunchMode('instrumental');else if(kind==='vocal'||kind==='all')_setLaunchMode('vocal');
    _aiSay('Done ✓');toast('Claude wrote the '+(kind==='all'?'full song':kind)+' for '+a);
  }catch(e){if(e.needsKey){_aiSay('needs API key');alert(e.msg||"Add ANTHROPIC_API_KEY in the Cloudflare Pages project (Settings → Variables and Secrets), then redeploy.");}else{_aiSay('failed');toast('AI failed: '+(e.message||e));}}
  finally{_aiBtns(false);setTimeout(()=>_aiSay(''),5000);}}
($('#aiGenAll')||{}).onclick=()=>_aiRun('all');
($('#aiGenInstrumental')||{}).onclick=()=>_aiRun('instrumental');
($('#aiGenVocal')||{}).onclick=()=>_aiRun('vocal');
($('#aiGenLyrics')||{}).onclick=()=>_aiRun('lyrics');
function _splitInstrumental(txt){txt=String(txt||'');let excl='';const ei=txt.search(/\bExclude:/i);if(ei>=0){excl=txt.slice(ei).replace(/^Exclude:\s*/i,'').trim();txt=txt.slice(0,ei).trim();}let style=txt,arr='';const ai=txt.search(/\bARRANGEMENT\s*:?/i);if(ai>=0){style=txt.slice(0,ai);arr=txt.slice(ai).replace(/^ARRANGEMENT\s*:?/i,'').trim();}style=style.replace(/^\s*STYLE\s*:?/i,'').trim();return {style,arrangement:arr,exclude:excl};}
function _copyTo(t,msg){navigator.clipboard.writeText(t||'');toast(msg);}
($('#aiCopyStyle')||{}).onclick=()=>{const a=_studioArtist();if(!a)return toast('Pick an artist');const s=_splitInstrumental(_studioStore(a).instrumental);_copyTo(s.style||_studioStore(a).instrumental,'Style copied → paste in Suno style box');};
($('#aiCopyArrangement')||{}).onclick=()=>{const a=_studioArtist();if(!a)return toast('Pick an artist');const s=_splitInstrumental(_studioStore(a).instrumental);_copyTo(s.arrangement||_studioStore(a).instrumental,'Arrangement copied → Suno lyrics box (Instrumental ON)');};
($('#aiCopyExclude')||{}).onclick=()=>{const a=_studioArtist();if(!a)return toast('Pick an artist');const s=_splitInstrumental(_studioStore(a).instrumental);_copyTo(s.exclude,'Exclude list copied → Suno exclude-styles');};
($('#aiCopyLyrics')||{}).onclick=()=>{const a=_studioArtist();if(!a)return toast('Pick an artist');_copyTo(_studioStore(a).lyrics,'Lyrics copied → Suno lyrics box');};
// ── A&R: Roster (artist CRUD) + Shop (WooCommerce product CRUD) ──────────────
function _arModal(title,fields,onSave){const wrap=document.createElement('div');wrap.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);display:grid;place-items:center;z-index:9999';const box=document.createElement('div');box.style.cssText='background:#12110c;border:1px solid #3a3320;border-radius:10px;max-width:520px;width:92%;max-height:88vh;overflow:auto;padding:20px';box.innerHTML=`<h2 style="margin:0 0 14px">${title}</h2>`+fields.map(f=>{if(f.type==='select')return `<label style="display:block;margin-bottom:10px;font-size:.8rem;color:#c9b98f">${f.label}<select data-k="${f.k}" style="width:100%;margin-top:4px;padding:8px;background:#0b0a07;border:1px solid #3a3320;border-radius:6px;color:#f0e6cf">${f.opts.map(o=>`<option ${o===f.val?'selected':''}>${o}</option>`).join('')}</select></label>`;if(f.type==='textarea')return `<label style="display:block;margin-bottom:10px;font-size:.8rem;color:#c9b98f">${f.label}<textarea data-k="${f.k}" rows="3" placeholder="${f.ph||''}" style="width:100%;margin-top:4px;padding:8px;background:#0b0a07;border:1px solid #3a3320;border-radius:6px;color:#f0e6cf;font-family:inherit">${f.val||''}</textarea></label>`;return `<label style="display:block;margin-bottom:10px;font-size:.8rem;color:#c9b98f">${f.label}<input data-k="${f.k}" type="${f.type||'text'}" value="${(f.val==null?'':String(f.val)).replace(/"/g,'&quot;')}" placeholder="${f.ph||''}" style="width:100%;margin-top:4px;padding:8px;background:#0b0a07;border:1px solid #3a3320;border-radius:6px;color:#f0e6cf"></label>`}).join('')+`<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px;align-items:center"><span data-msg style="flex:1;color:#d9534f;font-size:.78rem"></span><button class="button ghost" data-x>Cancel</button><button class="button" data-ok>Save</button></div>`;wrap.appendChild(box);document.body.appendChild(wrap);const close=()=>wrap.remove();box.querySelector('[data-x]').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close()};box.querySelector('[data-ok]').onclick=async()=>{const vals={};box.querySelectorAll('[data-k]').forEach(el=>vals[el.dataset.k]=el.value);const btn=box.querySelector('[data-ok]');btn.disabled=true;btn.textContent='Saving…';try{await onSave(vals);close();}catch(e){box.querySelector('[data-msg]').textContent=e.message||'Save failed';btn.disabled=false;btn.textContent='Save';}};}
async function NMC_renderRoster(){const box=$('#arRosterList');if(!box)return;try{const r=await api('/api/site/artists');const list=r.artists||[];box.innerHTML=list.length?list.map(a=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 4px;border-top:1px solid var(--line)">${a.thumbnail?`<img src="${a.thumbnail}" style="width:32px;height:32px;border-radius:50%;object-fit:cover">`:'<span style="width:32px;height:32px;border-radius:50%;background:#1a1a12;display:grid;place-items:center">♪</span>'}<div style="flex:1;min-width:0"><b>${a.name}</b><small style="display:block;color:var(--muted)">${a.genre||''}${a.origin?' · '+a.origin:''}</small></div><a class="button ghost small" href="${a.url||'#'}" target="_blank" rel="noopener">View</a><button class="button ghost small" data-art-edit="${a.id}">Edit</button><button class="button ghost small" data-art-del="${a.id}" data-name="${(a.name||'').replace(/"/g,'&quot;')}">Del</button></div>`).join(''):'<p class="muted-note" style="color:var(--muted)">No artists found.</p>';$$('[data-art-edit]').forEach(b=>b.onclick=()=>{const a=list.find(x=>String(x.id)===b.dataset.artEdit)||{};_arModal('Edit artist',[{k:'name',label:'Name',val:a.name},{k:'genre',label:'Genre',val:a.genre},{k:'origin',label:'Origin',val:a.origin},{k:'bpm',label:'Signature BPM',val:a.bpm},{k:'signature',label:'Signature phrase',val:a.signature},{k:'bio',label:'Bio',type:'textarea',val:a.bio}],async v=>{await api('/api/site/artist-save',{method:'POST',body:JSON.stringify({id:a.id,...v})});toast('Artist saved');NMC_renderRoster();})});$$('[data-art-del]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete artist "'+b.dataset.name+'"? Moves it to Trash on the site.'))return;try{await api('/api/site/artist-delete',{method:'POST',body:JSON.stringify({id:Number(b.dataset.artDel)})});toast('Artist deleted');NMC_renderRoster();}catch(e){toast(/404|502/.test(e.message)?'Install nmc-signalos-endpoints.php first':'Delete failed: '+e.message);}})}catch(e){box.innerHTML=`<p class="fail">Roster failed: ${e.message}</p>`}}
async function NMC_renderShop(){const box=$('#arShopList');if(!box)return;try{const r=await api('/api/site/shop-products');if(r&&r.stub){box.innerHTML='<p class="muted-note" style="color:var(--muted)">Shop CRUD endpoint not installed yet — paste <code>nmc-signalos-endpoints.php</code> at the end of nmc-core.php, then Refresh.</p>';return;}if(r&&r.woocommerce===false){box.innerHTML='<p class="muted-note" style="color:var(--muted)">WooCommerce not active on the site.</p>';return;}const list=r.products||[],cur=r.currency||'GBP';box.innerHTML=list.length?list.map(p=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 4px;border-top:1px solid var(--line)">${p.image?`<img src="${p.image}" style="width:34px;height:34px;border-radius:5px;object-fit:cover">`:'<span style="width:34px;height:34px;border-radius:5px;background:#1a1a12;display:grid;place-items:center">🛍</span>'}<div style="flex:1;min-width:0"><b>${p.name}</b><small style="display:block;color:var(--muted)">${p.sku?p.sku+' · ':''}${cur} ${p.price||'0'}${p.stock!=null?' · stock '+p.stock:''} · ${p.status}</small></div><button class="button ghost small" data-pr-edit="${p.id}">Edit</button><button class="button ghost small" data-pr-del="${p.id}" data-name="${(p.name||'').replace(/"/g,'&quot;')}">Del</button></div>`).join(''):'<p class="muted-note" style="color:var(--muted)">No products yet — add one.</p>';$$('[data-pr-edit]').forEach(b=>b.onclick=()=>{const p=list.find(x=>String(x.id)===b.dataset.prEdit)||{};_arModal('Edit product',[{k:'name',label:'Name',val:p.name},{k:'price',label:'Price ('+cur+')',type:'number',val:p.price},{k:'sku',label:'SKU',val:p.sku},{k:'stock',label:'Stock (blank = untracked)',type:'number',val:p.stock},{k:'status',label:'Status',type:'select',val:p.status,opts:['publish','draft','private']},{k:'image_url',label:'Image URL (optional)',type:'url'},{k:'description',label:'Description',type:'textarea'}],async v=>{await api('/api/site/product-save',{method:'POST',body:JSON.stringify({id:p.id,...v})});toast('Product saved');NMC_renderShop();})});$$('[data-pr-del]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete product "'+b.dataset.name+'"? Moves it to Trash.'))return;try{await api('/api/site/product-delete',{method:'POST',body:JSON.stringify({id:Number(b.dataset.prDel)})});toast('Product deleted');NMC_renderShop();}catch(e){toast(/404|502/.test(e.message)?'Install nmc-signalos-endpoints.php first':'Delete failed: '+e.message);}})}catch(e){box.innerHTML=/404|502/.test(e.message)?'<p class="muted-note" style="color:var(--muted)">Shop CRUD endpoint not installed yet — paste nmc-signalos-endpoints.php at the end of nmc-core.php, then Refresh.</p>':`<p class="fail">Shop failed: ${e.message}</p>`}}
($('#arRosterRefresh')||{}).onclick=()=>NMC_renderRoster();($('#arShopRefresh')||{}).onclick=()=>NMC_renderShop();
($('#arArtistAdd')||{}).onclick=()=>_arModal('Add artist',[{k:'name',label:'Name'},{k:'genre',label:'Genre'},{k:'origin',label:'Origin'},{k:'signature',label:'Signature phrase'},{k:'bio',label:'Bio',type:'textarea'}],async v=>{if(!v.name)throw new Error('Name required');await api('/api/site/artist-save',{method:'POST',body:JSON.stringify(v)});toast('Artist created');NMC_renderRoster();});
($('#arProductAdd')||{}).onclick=()=>_arModal('Add product',[{k:'name',label:'Name'},{k:'price',label:'Price',type:'number'},{k:'sku',label:'SKU'},{k:'stock',label:'Stock (blank = untracked)',type:'number'},{k:'status',label:'Status',type:'select',val:'publish',opts:['publish','draft','private']},{k:'image_url',label:'Image URL (optional)',type:'url'},{k:'description',label:'Description',type:'textarea'}],async v=>{if(!v.name)throw new Error('Name required');await api('/api/site/product-save',{method:'POST',body:JSON.stringify(v)});toast('Product created');NMC_renderShop();});
